content.content:
1	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
2	
3	:root {
4	  --gold: #c8a96e;
5	  --gold-light: #dfc48e;
6	  --dark: #0c0c0c;
7	  --dark2: #141414;
8	  --dark3: #1e1e1e;
9	  --border: rgba(200,169,110,0.18);
10	  --text: #e2e2e2;
11	  --muted: #888;
12	  --r: 10px;
13	  --ease: 0.3s ease;
14	}
15	
16	html { scroll-behavior: smooth; }
17	
18	body {
19	  font-family: 'Noto Sans TC', 'PingFang TC', 'Microsoft JhengHei', sans-serif;
20	  background: var(--dark);
21	  color: var(--text);
22	  line-height: 1.75;
23	  font-size: 15px;
24	}
25	
26	.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
27	.gold { color: var(--gold); }
28	.center { text-align: center; }
29	.mt-40 { margin-top: 40px; }
30	img { max-width: 100%; display: block; }
31	a { color: inherit; text-decoration: none; }
32	section { padding: 100px 0; }
33	
34	/* 標籤 */
35	.tag {
36	  font-size: 12px;
37	  letter-spacing: 3px;
38	  text-transform: uppercase;
39	  color: var(--gold);
40	  margin-bottom: 14px;
41	  font-weight: 600;
42	  display: block;
43	}
44	
45	/* 區段標題 */
46	.section-title {
47	  font-family: 'Noto Serif TC', serif;
48	  font-size: clamp(26px, 3.5vw, 40px);
49	  font-weight: 700;
50	  line-height: 1.3;
51	  margin-bottom: 52px;
52	}
53	
54	/* 按鈕 */
55	.btn-gold {
56	  display: inline-block;
57	  background: var(--gold);
58	  color: #0c0c0c;
59	  padding: 14px 32px;
60	  border-radius: 4px;
61	  font-weight: 700;
62	  font-size: 15px;
63	  letter-spacing: 1px;
64	  transition: background var(--ease), transform var(--ease);
65	  cursor: pointer;
66	  border: none;
67	  font-family: inherit;
68	}
69	.btn-gold:hover { background: var(--gold-light); transform: translateY(-2px); }
70	
71	.btn-line {
72	  display: inline-block;
73	  border: 2px solid var(--gold);
74	  color: var(--gold);
75	  padding: 12px 32px;
76	  border-radius: 4px;
77	  font-weight: 700;
78	  font-size: 15px;
79	  letter-spacing: 1px;
80	  transition: all var(--ease);
81	}
82	.btn-line:hover { background: var(--gold); color: #0c0c0c; transform: translateY(-2px); }
83	
84	.btn-outline {
85	  display: inline-block;
86	  border: 2px solid rgba(200,169,110,0.5);
87	  color: var(--gold);
88	  padding: 12px 32px;
89	  border-radius: 4px;
90	  font-weight: 700;
91	  font-size: 15px;
92	  transition: all var(--ease);
93	}
94	.btn-outline:hover { border-color: var(--gold); background: rgba(200,169,110,0.08); }
95	
96	.hero-btns { display: flex; gap: 16px; flex-wrap: wrap; }
97	
98	/* ===== NAVBAR ===== */
99	.navbar {
100	  position: fixed; top: 0; left: 0; right: 0;
101	  z-index: 1000;
102	  transition: background var(--ease), box-shadow var(--ease);
103	}
104	.navbar.scrolled {
105	  background: rgba(12,12,12,0.97);
106	  box-shadow: 0 2px 24px rgba(0,0,0,0.6);
107	}
108	.nav-inner {
109	  display: flex; align-items: center;
110	  justify-content: space-between;
111	  height: 70px;
112	}
113	.logo { display: flex; flex-direction: column; line-height: 1.1; }
114	.logo-main {
115	  font-family: 'Noto Serif TC', serif;
116	  font-size: 20px; font-weight: 900;
117	  color: var(--gold); letter-spacing: 3px;
118	}
119	.logo-sub { font-size: 10px; letter-spacing: 2px; color: var(--muted); margin-top: 1px; }
120	
121	.nav-links { display: flex; align-items: center; gap: 28px; }
122	.nav-links a {
123	  font-size: 14px; color: var(--text);
124	  letter-spacing: 1px;
125	  position: relative;
126	  transition: color var(--ease);
127	}
128	.nav-links a::after {
129	  content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
130	  height: 1px; background: var(--gold);
131	  transform: scaleX(0); transition: transform var(--ease);
132	}
133	.nav-links a:hover { color: var(--gold); }
134	.nav-links a:hover::after { transform: scaleX(1); }
135	
136	.btn-nav {
137	  background: var(--gold) !important; color: #0c0c0c !important;
138	  padding: 9px 20px; border-radius: 4px; font-weight: 700;
139	}
140	.btn-nav::after { display: none !important; }
141	.btn-nav:hover { background: var(--gold-light) !important; }
142	
143	.hamburger { display: none; flex-direction: column; gap: 5px; background: none; border: none; cursor: pointer; }
144	.hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all var(--ease); }
145	.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
146	.hamburger.open span:nth-child(2) { opacity: 0; }
147	.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }
148	
149	.mobile-menu { display: none; flex-direction: column; padding: 16px 24px 24px; background: rgba(12,12,12,0.98); border-top: 1px solid var(--border); }
150	.mobile-menu a { padding: 13px 0; font-size: 16px; border-bottom: 1px solid rgba(255,255,255,0.06); }
151	.mobile-menu a:last-child { border: none; color: var(--gold); font-weight: 700; margin-top: 8px; }
152	.mobile-menu.open { display: flex; }
153	
154	/* ===== HERO ===== */
155	.hero {
156	  position: relative; min-height: 100vh;
157	  display: flex; align-items: center;
158	  background: var(--dark);
159	  overflow: hidden;
160	}
161	.hero-bg {
162	  position: absolute; inset: 0;
163	  background:
164	    radial-gradient(ellipse 70% 60% at 75% 50%, rgba(200,169,110,0.07) 0%, transparent 60%),
165	    radial-gradient(ellipse 50% 40% at 15% 85%, rgba(200,169,110,0.04) 0%, transparent 55%),
166	    linear-gradient(135deg, #0c0c0c 0%, #141008 50%, #0c0f0c 100%);
167	}
168	.hero-content { position: relative; z-index: 1; max-width: 680px; padding-top: 70px; }
169	.hero-tag { font-size: 12px; letter-spacing: 4px; color: var(--gold); margin-bottom: 22px; text-transform: uppercase; }
170	.hero-title {
171	  font-family: 'Noto Serif TC', serif;
172	  font-size: clamp(48px, 7vw, 88px);
173	  font-weight: 900; line-height: 1.1;
174	  color: #fff; margin-bottom: 24px;
175	}
176	.hero-desc { font-size: 17px; color: rgba(226,226,226,0.75); line-height: 1.9; margin-bottom: 36px; }
177	
178	.scroll-hint { position: absolute; bottom: 36px; left: 50%; transform: translateX(-50%); }
179	.scroll-hint span {
180	  display: block; width: 1px; height: 56px;
181	  background: linear-gradient(to bottom, var(--gold), transparent);
182	  animation: scroll 1.6s ease-in-out infinite;
183	}
184	@keyframes scroll {
185	  0%,100% { opacity: 0; transform: scaleY(0.3); }
186	  50% { opacity: 1; transform: scaleY(1); }
187	}
188	
189	/* ===== PAIN ===== */
190	.pain { background: var(--dark2); padding: 90px 0; }
191	.pain-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 20px; margin-top: 16px; }
192	.pain-card {
193	  background: var(--dark3); border: 1px solid var(--border);
194	  border-radius: var(--r); padding: 32px 24px;
195	  transition: border-color var(--ease), transform var(--ease);
196	}
197	.pain-card:hover { border-color: var(--gold); transform: translateY(-4px); }
198	.pain-icon { font-size: 36px; margin-bottom: 14px; }
199	.pain-card h3 { font-family: 'Noto Serif TC', serif; font-size: 18px; color: var(--gold); margin-bottom: 10px; font-weight: 700; }
200	.pain-card p { font-size: 14px; color: var(--muted); line-height: 1.8; }
201	
202	/* ===== STATS ===== */
203	.stats {
204	  padding: 68px 0;
205	  background: linear-gradient(90deg, #0c0c0c, #141008 50%, #0c0c0c);
206	  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
207	}
208	.stats-grid { display: grid; grid-template-columns: repeat(4,1fr); }
209	.stat-item {
210	  display: flex; flex-direction: column; align-items: center; text-align: center;
211	  padding: 0 20px; border-right: 1px solid var(--border);
212	}
213	.stat-item:last-child { border-right: none; }
214	.stat-num {
215	  font-family: 'Noto Serif TC', serif;
216	  font-size: clamp(34px, 4vw, 52px); font-weight: 900;
217	  color: var(--gold); line-height: 1; display: inline;
218	}
219	.stat-unit { font-size: clamp(14px, 1.5vw, 18px); color: var(--gold); font-weight: 700; }
220	.stat-label { font-size: 12px; color: var(--muted); letter-spacing: 1px; margin-top: 6px; }
221	
222	/* ===== ABOUT ===== */
223	.about { background: var(--dark); }
224	.about-inner { display: grid; grid-template-columns: 1fr 1.25fr; gap: 72px; align-items: center; }
225	.about-photo { position: relative; }
226	.about-photo img { width: 100%; border-radius: var(--r); filter: grayscale(15%); }
227	.photo-fallback {
228	  display: none; width: 100%; aspect-ratio: 4/5;
229	  background: var(--dark3); border: 1px solid var(--border);
230	  border-radius: var(--r); align-items: center; justify-content: center;
231	  font-family: 'Noto Serif TC', serif; font-size: 48px; font-weight: 900;
232	  color: var(--gold); text-align: center; line-height: 1.2;
233	}
234	.photo-badge {
235	  position: absolute; bottom: 28px; right: -18px;
236	  background: var(--gold); color: #0c0c0c;
237	  padding: 14px 18px; border-radius: var(--r);
238	  font-weight: 900; font-size: 13px; text-align: center; line-height: 1.4;
239	  box-shadow: 0 8px 28px rgba(200,169,110,0.3);
240	}
241	.about-text h2 {
242	  font-family: 'Noto Serif TC', serif;
243	  font-size: clamp(24px, 3vw, 34px); font-weight: 700; line-height: 1.35; margin-bottom: 20px;
244	}
245	.about-text blockquote {
246	  font-family: 'Noto Serif TC', serif;
247	  font-size: 16px; color: var(--gold);
248	  border-left: 3px solid var(--gold); padding-left: 18px;
249	  margin: 22px 0; line-height: 1.8; font-style: italic;
250	}
251	.about-text p { color: rgba(226,226,226,0.78); line-height: 1.9; margin-bottom: 14px; font-size: 15px; }
252	.identity-tags { display: flex; flex-direction: column; gap: 8px; margin: 22px 0; }
253	.identity-tags span { font-size: 14px; color: var(--gold); font-weight: 600; }
254	.about-skills { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0 28px; }
255	.about-skills span {
256	  border: 1px solid rgba(200,169,110,0.4); color: var(--gold);
257	  padding: 5px 14px; border-radius: 100px; font-size: 13px;
258	}
259	
260	/* ===== QUOTE ===== */
261	.quote-section {
262	  padding: 80px 0;
263	  background: linear-gradient(135deg, #141008, #0c0f0c);
264	  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
265	}
266	.big-quote { text-align: center; max-width: 700px; margin: 0 auto; }
267	.quote-mark { font-size: 64px; color: var(--gold); opacity: 0.3; line-height: 0.5; display: block; margin-bottom: 16px; }
268	.big-quote p {
269	  font-family: 'Noto Serif TC', serif;
270	  font-size: clamp(20px, 3vw, 28px); font-weight: 700;
271	  line-height: 1.6; color: #fff;
272	}
273	.big-quote cite { display: block; margin-top: 20px; font-size: 14px; color: var(--gold); letter-spacing: 2px; font-style: normal; }
274	
275	/* ===== SERVICES ===== */
276	.services { background: var(--dark2); }
277	.services-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
278	.service-card {
279	  background: var(--dark3); border: 1px solid rgba(255,255,255,0.07);
280	  border-radius: var(--r); padding: 44px 32px;
281	  position: relative; overflow: hidden;
282	  transition: border-color var(--ease), transform var(--ease);
283	}
284	.service-card::before {
285	  content: ''; position: absolute; top: 0; left: 0; right: 0;
286	  height: 3px; background: transparent; transition: background var(--ease);
287	}
288	.service-card:hover { border-color: rgba(200,169,110,0.3); transform: translateY(-5px); }
289	.service-card:hover::before, .service-card.featured::before { background: var(--gold); }
290	.service-card.featured { border-color: rgba(200,169,110,0.35); background: linear-gradient(135deg, #1a1a14, #1e1e1e); }
291	.svc-num { font-family: 'Noto Serif TC', serif; font-size: 44px; font-weight: 900; color: rgba(200,169,110,0.12); line-height: 1; margin-bottom: 14px; }
292	.service-card h3 { font-family: 'Noto Serif TC', serif; font-size: 21px; font-weight: 700; color: var(--gold); margin-bottom: 14px; }
293	.service-card > p { font-size: 14px; color: var(--muted); line-height: 1.8; margin-bottom: 22px; }
294	.service-card ul { list-style: none; margin-bottom: 28px; }
295	.service-card ul li {
296	  font-size: 14px; color: rgba(226,226,226,0.65);
297	  padding: 7px 0 7px 16px; border-bottom: 1px solid rgba(255,255,255,0.05);
298	  position: relative;
299	}
300	.service-card ul li::before { content: '›'; position: absolute; left: 0; color: var(--gold); }
301	.svc-link { font-size: 13px; color: var(--gold); font-weight: 600; letter-spacing: 1px; transition: letter-spacing var(--ease); }
302	.svc-link:hover { letter-spacing: 3px; }
303	
304	/* ===== COURSES ===== */
305	.courses { background: var(--dark); }
306	.courses-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
307	.course-card {
308	  background: var(--dark2); border-radius: var(--r); overflow: hidden;
309	  border: 1px solid rgba(255,255,255,0.06);
310	  transition: transform var(--ease), border-color var(--ease);
311	}
312	.course-card:hover { transform: translateY(-4px); border-color: rgba(200,169,110,0.3); }
313	.course-cover {
314	  height: 150px; display: flex; align-items: center; justify-content: center;
315	  font-family: 'Noto Serif TC', serif; font-size: 21px; font-weight: 700;
316	  color: rgba(200,169,110,0.65); text-align: center; line-height: 1.4;
317	  border-bottom: 1px solid rgba(200,169,110,0.1);
318	}
319	.c1 { background: linear-gradient(135deg, #0d1520, #1a2035); }
320	.c2 { background: linear-gradient(135deg, #0a1f1f, #102020); }
321	.c3 { background: linear-gradient(135deg, #160a26, #1a0f2e); }
322	.c4 { background: linear-gradient(135deg, #0a1a0a, #0f200f); }
323	.c5 { background: linear-gradient(135deg, #1a150a, #201a0a); }
324	.c6 { background: linear-gradient(135deg, #1a0a0a, #200f0f); }
325	.course-body { padding: 22px; }
326	.course-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
327	.course-tags span { font-size: 11px; background: rgba(200,169,110,0.13); color: var(--gold); padding: 2px 9px; border-radius: 100px; }
328	.course-body h3 { font-size: 15px; font-weight: 700; margin-bottom: 7px; line-height: 1.4; }
329	.course-body > p { font-size: 13px; color: var(--muted); margin-bottom: 14px; line-height: 1.6; }
330	.course-price { display: flex; align-items: baseline; gap: 10px; margin-bottom: 14px; }
331	.course-price b { font-size: 19px; color: var(--gold); }
332	.course-price s { font-size: 12px; color: var(--muted); }
333	.btn-course {
334	  display: block; text-align: center;
335	  border: 1px solid var(--gold); color: var(--gold);
336	  padding: 9px; border-radius: 4px; font-size: 13px; font-weight: 600;
337	  transition: all var(--ease);
338	}
339	.btn-course:hover { background: var(--gold); color: #0c0c0c; }
340	
341	/* ===== SPEAKING ===== */
342	.speaking { background: var(--dark2); }
343	.speaking-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; margin-bottom: 52px; }
344	.speaking-card {
345	  background: var(--dark3); border: 1px solid rgba(255,255,255,0.06);
346	  border-radius: var(--r); padding: 32px 24px;
347	  transition: all var(--ease);
348	}
349	.speaking-card:hover { border-color: rgba(200,169,110,0.3); transform: translateY(-4px); }
350	.sp-icon { font-size: 32px; margin-bottom: 14px; }
351	.speaking-card h3 { font-size: 16px; font-weight: 700; color: var(--gold); margin-bottom: 9px; }
352	.speaking-card p { font-size: 13px; color: var(--muted); line-height: 1.7; }
353	.speaking-footer {
354	  text-align: center; padding: 40px;
355	  border: 1px solid var(--border); border-radius: var(--r);
356	  background: linear-gradient(135deg, rgba(200,169,110,0.05), transparent);
357	}
358	.speaking-footer p { font-size: 17px; color: rgba(226,226,226,0.8); margin-bottom: 24px; }
359	.speaking-footer strong { color: var(--gold); font-size: 21px; }
360	
361	/* ===== TESTIMONIALS ===== */
362	.testimonials { background: var(--dark); }
363	.testi-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 20px; }
364	.testi-card {
365	  background: var(--dark2); border: 1px solid var(--border);
366	  border-radius: var(--r); padding: 32px 28px;
367	}
368	.stars { color: var(--gold); font-size: 16px; margin-bottom: 14px; letter-spacing: 2px; }
369	.testi-card > p { font-size: 14px; color: rgba(226,226,226,0.78); line-height: 1.85; margin-bottom: 22px; font-style: italic; }
370	.testi-author { display: flex; align-items: center; gap: 12px; }
371	.avatar {
372	  width: 42px; height: 42px; border-radius: 50%;
373	  background: var(--gold); color: #0c0c0c;
374	  display: flex; align-items: center; justify-content: center;
375	  font-weight: 900; font-size: 17px; flex-shrink: 0;
376	}
377	.testi-author strong { display: block; font-size: 14px; }
378	.testi-author span { font-size: 12px; color: var(--muted); }
379	
380	/* ===== CTA ===== */
381	.cta-banner {
382	  padding: 90px 0;
383	  background: linear-gradient(135deg, #141008, #0c0f0c);
384	  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
385	  text-align: center;
386	}
387	.cta-inner h2 { font-family: 'Noto Serif TC', serif; font-size: clamp(26px, 4vw, 42px); font-weight: 900; margin-bottom: 14px; color: #fff; }
388	.cta-inner p { font-size: 16px; color: rgba(226,226,226,0.7); margin-bottom: 36px; line-height: 1.8; }
389	.cta-inner .hero-btns { justify-content: center; }
390	
391	/* ===== CONTACT ===== */
392	.contact { background: var(--dark2); }
393	.contact-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 72px; align-items: start; }
394	.contact-info h2 { font-family: 'Noto Serif TC', serif; font-size: clamp(24px, 3vw, 34px); font-weight: 700; line-height: 1.4; margin-bottom: 18px; }
395	.contact-info > p { color: rgba(226,226,226,0.7); line-height: 1.9; margin-bottom: 32px; }
396	.contact-list { list-style: none; display: flex; flex-direction: column; gap: 20px; }
397	.contact-list li { display: flex; align-items: flex-start; gap: 14px; }
398	.contact-list li > span { font-size: 22px; flex-shrink: 0; margin-top: 2px; }
399	.contact-list strong { display: block; font-size: 12px; color: var(--muted); letter-spacing: 1px; margin-bottom: 3px; text-transform: uppercase; }
400	.contact-list a { color: var(--gold); font-size: 15px; font-weight: 600; transition: opacity var(--ease); }
401	.contact-list a:hover { opacity: 0.7; }
402	
403	.subscribe-box {
404	  background: var(--dark3); border: 1px solid var(--border);
405	  border-radius: var(--r); padding: 44px 36px;
406	}
407	.subscribe-box h3 { font-family: 'Noto Serif TC', serif; font-size: 21px; font-weight: 700; line-height: 1.4; margin-bottom: 10px; color: var(--gold); }
408	.subscribe-box > p { font-size: 13px; color: var(--muted); margin-bottom: 26px; line-height: 1.7; }
409	.subscribe-form { display: flex; flex-direction: column; gap: 11px; }
410	.subscribe-form input {
411	  background: var(--dark2); border: 1px solid rgba(255,255,255,0.1);
412	  border-radius: 4px; padding: 13px 15px; font-size: 14px;
413	  color: var(--text); font-family: inherit; outline: none;
414	  transition: border-color var(--ease);
415	}
416	.subscribe-form input:focus { border-color: var(--gold); }
417	.subscribe-form input::placeholder { color: var(--muted); }
418	.subscribe-form button {
419	  width: 100%; padding: 14px; background: var(--gold); color: #0c0c0c;
420	  border: none; border-radius: 4px; font-weight: 700; font-size: 15px;
421	  cursor: pointer; font-family: inherit; transition: background var(--ease);
422	}
423	.subscribe-form button:hover { background: var(--gold-light); }
424	.sub-note { font-size: 12px; color: var(--muted); margin-top: 10px; line-height: 1.6; }
425	
426	/* ===== FOOTER ===== */
427	.footer { background: var(--dark); border-top: 1px solid rgba(200,169,110,0.1); padding: 68px 0 0; }
428	.footer-inner { display: grid; grid-template-columns: 1.8fr 1fr 1fr 1fr; gap: 40px; padding-bottom: 48px; }
429	.footer-brand .logo-main { font-family: 'Noto Serif TC', serif; font-size: 21px; font-weight: 900; color: var(--gold); letter-spacing: 3px; display: block; }
430	.footer-brand .logo-sub { font-size: 10px; letter-spacing: 2px; color: var(--muted); display: block; margin-bottom: 14px; }
431	.footer-brand p { font-size: 13px; color: var(--muted); line-height: 1.8; }
432	.footer-identity { display: flex; flex-direction: column; gap: 4px; margin-top: 12px; }
433	.footer-identity span { font-size: 12px; color: rgba(200,169,110,0.6); }
434	.footer-col h4 { font-size: 12px; letter-spacing: 2px; color: var(--gold); margin-bottom: 14px; text-transform: uppercase; }
435	.footer-col { display: flex; flex-direction: column; }
436	.footer-col a { font-size: 13px; color: var(--muted); padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,0.04); transition: color var(--ease); }
437	.footer-col a:hover { color: var(--gold); }
438	.footer-bottom { border-top: 1px solid rgba(255,255,255,0.06); padding: 18px 0; text-align: center; }
439	.footer-bottom p { font-size: 12px; color: var(--muted); }
440	
441	/* ===== QUOTES CAROUSEL ===== */
442	.quotes-carousel { background: var(--dark); }
443	.carousel-wrapper {
444	  position: relative;
445	  max-width: 1100px;
446	  margin: 48px auto 0;
447	}
448	.carousel-viewport { overflow: hidden; padding: 0 4px; }
449	.carousel-track {
450	  display: flex;
451	  transition: transform 0.4s ease;
452	}
453	.carousel-card {
454	  flex: 0 0 calc(33.333% - 16px);
455	  margin: 0 8px;
456	  background: var(--dark3);
457	  border: 1px solid var(--border);
458	  border-radius: var(--r);
459	  padding: 36px 28px 24px;
460	  display: flex;
461	  flex-direction: column;
462	  min-height: 200px;
463	  position: relative;
464	  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
465	  cursor: default;
466	}
467	.carousel-card:hover {
468	  transform: translateY(-4px);
469	  box-shadow: 0 16px 32px rgba(0,0,0,0.5), 0 0 16px rgba(200,169,110,0.1);
470	  border-color: var(--gold);
471	}
472	.card-quote-mark {
473	  position: absolute;
474	  top: 12px;
475	  left: 16px;
476	  font-size: 32px;
477	  color: var(--gold);
478	  opacity: 0.2;
479	  line-height: 1;
480	}
481	.card-text {
482	  font-size: 15px;
483	  line-height: 1.8;
484	  color: var(--text);
485	  flex-grow: 1;
486	  margin-top: 8px;
487	}
488	.card-tag {
489	  display: inline-block;
490	  margin-top: 16px;
491	  padding: 3px 10px;
492	  font-size: 11px;
493	  color: var(--gold);
494	  border: 1px solid var(--border);
495	  border-radius: 20px;
496	  align-self: flex-start;
497	}
498	.carousel-btn {
499	  position: absolute;
500	  top: 50%;
501	  transform: translateY(-50%);
502	  width: 44px;
503	  height: 44px;
504	  border-radius: 50%;
505	  border: 1px solid var(--border);
506	  background: var(--dark);
507	  color: var(--text);
508	  font-size: 24px;
509	  cursor: pointer;
510	  z-index: 2;
511	  transition: all var(--ease);
512	  display: flex;
513	  align-items: center;
514	  justify-content: center;
515	}
516	.carousel-btn:hover { border-color: var(--gold); color: var(--gold); }
517	.carousel-prev { left: -56px; }
518	.carousel-next { right: -56px; }
519	.carousel-dots {
520	  display: flex;
521	  justify-content: center;
522	  gap: 6px;
523	  margin-top: 24px;
524	  flex-wrap: wrap;
525	}
526	.carousel-dots button {
527	  width: 8px;
528	  height: 8px;
529	  border-radius: 50%;
530	  border: none;
531	  background: var(--border);
532	  cursor: pointer;
533	  transition: all var(--ease);
534	  padding: 0;
535	}
536	.carousel-dots button.active { background: var(--gold); width: 20px; border-radius: 4px; }
537	.carousel-nav-bottom {
538	  display: flex;
539	  justify-content: center;
540	  align-items: center;
541	  gap: 20px;
542	  margin-top: 16px;
543	}
544	.carousel-nav-btn {
545	  padding: 8px 20px;
546	  border: 1px solid var(--border);
547	  background: none;
548	  color: var(--text);
549	  font-size: 14px;
550	  border-radius: var(--r);
551	  cursor: pointer;
552	  transition: all var(--ease);
553	}
554	.carousel-nav-btn:hover { border-color: var(--gold); color: var(--gold); }
555	.carousel-counter { font-size: 13px; color: var(--muted); min-width: 60px; text-align: center; }
556	
557	@media (max-width: 1200px) {
558	  .carousel-prev { left: -8px; }
559	  .carousel-next { right: -8px; }
560	}
561	@media (max-width: 1024px) {
562	  .carousel-card { flex: 0 0 calc(50% - 16px); }
563	}
564	@media (max-width: 768px) {
565	  .carousel-card { flex: 0 0 calc(100% - 16px); }
566	  .carousel-prev { left: -4px; }
567	  .carousel-next { right: -4px; }
568	  .carousel-btn { width: 36px; height: 36px; font-size: 20px; }
569	}
570	
571	/* ===== TIMELINE ===== */
572	.timeline { background: var(--dark2); }
573	.timeline-track {
574	  position: relative;
575	  max-width: 720px;
576	  margin: 48px auto 0;
577	  padding-left: 40px;
578	}
579	.timeline-track::before {
580	  content: '';
581	  position: absolute;
582	  left: 14px;
583	  top: 0;
584	  bottom: 0;
585	  width: 2px;
586	  background: linear-gradient(to bottom, var(--gold), var(--border));
587	}
588	.tl-item {
589	  position: relative;
590	  padding: 0 0 32px 32px;
591	  display: flex;
592	  align-items: flex-start;
593	  gap: 20px;
594	}
595	.tl-item:last-child { padding-bottom: 0; }
596	.tl-item::before {
597	  content: '';
598	  position: absolute;
599	  left: -33px;
600	  top: 6px;
601	  width: 10px;
602	  height: 10px;
603	  border-radius: 50%;
604	  background: var(--muted);
605	  border: 2px solid var(--dark2);
606	  z-index: 1;
607	}
608	.tl-item.highlight::before {
609	  background: var(--gold);
610	  width: 14px;
611	  height: 14px;
612	  left: -35px;
613	  top: 4px;
614	  box-shadow: 0 0 12px rgba(200,169,110,0.5);
615	}
616	.tl-year {
617	  font-family: 'Noto Serif TC', serif;
618	  font-size: 18px;
619	  font-weight: 700;
620	  color: var(--gold);
621	  min-width: 52px;
622	  flex-shrink: 0;
623	}
624	.tl-content h4 {
625	  font-size: 16px;
626	  font-weight: 700;
627	  color: var(--text);
628	  margin-bottom: 2px;
629	}
630	.tl-content p {
631	  font-size: 14px;
632	  color: var(--muted);
633	  line-height: 1.5;
634	}
635	
636	/* ===== LINE FLOAT ===== */
637	.line-float {
638	  position: fixed; bottom: 28px; right: 28px;
639	  width: 54px; height: 54px; border-radius: 50%;
640	  box-shadow: 0 4px 20px rgba(6,199,85,0.4); z-index: 999;
641	  transition: transform var(--ease), box-shadow var(--ease);
642	  display: flex; align-items: center; justify-content: center;
643	}
644	.line-float:hover { transform: translateY(-3px) scale(1.06); box-shadow: 0 8px 28px rgba(6,199,85,0.5); }
645	.line-float svg { width: 100%; height: 100%; }
646	
647	/* ===== FADE IN ===== */
648	.fade { opacity: 0; transform: translateY(20px); transition: opacity 0.5s ease, transform 0.5s ease; }
649	.fade.in { opacity: 1; transform: translateY(0); }
650	
651	/* ===== RWD ===== */
652	@media (max-width: 1024px) {
653	  .pain-grid, .services-grid, .courses-grid, .testi-grid { grid-template-columns: repeat(2,1fr); }
654	  .speaking-grid { grid-template-columns: repeat(2,1fr); }
655	  .stats-grid { grid-template-columns: repeat(2,1fr); }
656	  .stat-item { border-right: none; border-bottom: 1px solid var(--border); padding: 20px; }
657	  .stat-item:last-child, .stat-item:nth-child(2) { border-bottom: none; }
658	  .about-inner, .contact-inner { grid-template-columns: 1fr; gap: 48px; }
659	  .footer-inner { grid-template-columns: 1fr 1fr; }
660	}
661	@media (max-width: 768px) {
662	  .nav-links { display: none; }
663	  .hamburger { display: flex; }
664	  .pain-grid, .services-grid, .courses-grid, .speaking-grid, .testi-grid { grid-template-columns: 1fr; }
665	  .stats-grid { grid-template-columns: repeat(2,1fr); }
666	  .footer-inner { grid-template-columns: 1fr; }
667	  section { padding: 72px 0; }
668	  .photo-badge { right: 12px; }
669	  .timeline-track { padding-left: 28px; }
670	  .tl-item { gap: 14px; padding-left: 24px; }
671	  .tl-year { font-size: 16px; min-width: 44px; }
672	  .tl-content h4 { font-size: 15px; }
673	}
674	@media (max-width: 480px) {
675	  .stats-grid { grid-template-columns: 1fr; }
676	  .stat-item { border-bottom: 1px solid var(--border); }
677	  .stat-item:last-child { border-bottom: none; }
678	  .hero-btns { flex-direction: column; }
679	  .subscribe-box { padding: 30px 20px; }
680	  .line-float { bottom: 16px; right: 16px; width: 46px; height: 46px; }
681	}
