input.command:
# 用 sips 兩步驟：先裁切高度（從頂部保留58%），再縮放
# sips -c 會從中心裁，所以要用 resampleHeightWidth 配合 crop
# 其實 sips 有 --crop 可以裁切
# 原檔 6336x9504，要保留上方 58% = 5512px

# sips --cropToHeightWidth 從中心裁，不是從頂部
# 所以用 osascript + NSImage 來裁

osascript -l JavaScript -e '
  ObjC.import("AppKit");
  ObjC.import("Foundation");

  var img = $.NSImage.alloc.initWithContentsOfFile("/Users/bymyway/Downloads/DSC03857.JPG");
  var size = img.size;
  var w = size.width;
  var h = size.height;

  // 裁切上方58%
  var cropH = Math.floor(h * 0.58);
  // NSRect: origin is bottom-left in AppKit
  var cropRect = $.NSMakeRect(0, h - cropH, w, cropH);

  var croppedRef = img.CGImageForProposedRect(null, null, null);

  // 用 CGImage 裁切
